import 'package:flutter/painting.dart';

import '../../screens/common/auth/launch/lf_css.dart' show CssBg, CssShadow, CssSolid;

/// Lys modus: one design theme class (`.mkN` in the export) — what it sets in
/// the dark mode ([dark], `:root:not([data-ae-modus="lys"]) .mkN`) and in the
/// light mode ([light], `:root[data-ae-modus="lys"] .mkN`). A null side sets
/// nothing in that mode: the element keeps its own (inline) style there.
///
/// The consts live in `mk_stil.g.dart` (generated by `ui-tools/lys/mk2dart.py`);
/// widgets read them through `context.mk(mkN)` (modus_scope.dart).
class MkStil {
  const MkStil(this.navn, {this.dark, this.light});

  final String navn;
  final MkVerdi? dark;
  final MkVerdi? light;

  /// The side for [lys] (null when the class sets nothing in that mode).
  MkVerdi? side(bool lys) => lys ? light : dark;
}

/// The CSS declarations of one side of a theme class, as Dart values.
class MkVerdi {
  const MkVerdi({
    this.farge,
    this.bg,
    this.skygge,
    this.kant,
    this.kantTopp,
    this.kantBunn,
    this.kantToppFarge,
    this.radius,
    this.rund = false,
    this.hjorner,
    this.strek,
    this.fyll,
    this.markor,
    this.v0,
    this.v1,
    this.v0Farge,
    this.v1Farge,
    this.raa,
  });

  /// `color`.
  final Color? farge;

  /// `background` layers, first = top (CSS order). Empty = `none`.
  final List<CssBg>? bg;

  /// `box-shadow`. Empty = `none`.
  final List<CssShadow>? skygge;

  /// `border` / `border-top` / `border-bottom`.
  final MkKant? kant;
  final MkKant? kantTopp;
  final MkKant? kantBunn;

  /// `border-top-color`.
  final Color? kantToppFarge;

  /// `border-radius` in px; [rund] = `50%`; [hjorner] = four corners
  /// (top-left, top-right, bottom-right, bottom-left).
  final double? radius;
  final bool rund;
  final List<double>? hjorner;

  /// SVG `stroke` / `fill`, input `caret-color`.
  final Color? strek;
  final Color? fyll;
  final Color? markor;

  /// The element's `--v0` / `--v1` custom properties (read by its inline
  /// style through `var(--v0)`): shadows, or a colour.
  final List<CssShadow>? v0;
  final List<CssShadow>? v1;
  final Color? v0Farge;
  final Color? v1Farge;

  /// Declarations the generator could not turn into Dart (ported by hand),
  /// as written in the CSS.
  final Map<String, String>? raa;

  /// The first background layer's colour when it is a plain colour.
  Color? get bgFarge {
    final b = bg;
    if (b == null || b.isEmpty) return null;
    final f = b.first;
    return f is CssSolid ? f.color : null;
  }

  BorderRadius? get borderRadius {
    final h = hjorner;
    if (h != null && h.length == 4) {
      return BorderRadius.only(
        topLeft: Radius.circular(h[0]),
        topRight: Radius.circular(h[1]),
        bottomRight: Radius.circular(h[2]),
        bottomLeft: Radius.circular(h[3]),
      );
    }
    final r = radius;
    return r == null ? null : BorderRadius.circular(r);
  }
}

/// A CSS border side: `<bredde>px solid|dashed <farge>`; [ingen] = `none`.
class MkKant {
  const MkKant(this.bredde, this.farge, {this.stiplet = false});

  static const MkKant ingen = MkKant(0, Color(0x00000000));

  final double bredde;
  final Color farge;
  final bool stiplet;

  bool get erIngen => bredde == 0;

  /// The [Border] for a box (all four sides), or null for `none`.
  Border? get border => erIngen ? null : Border.all(color: farge, width: bredde);

  BorderSide get side => erIngen ? BorderSide.none : BorderSide(color: farge, width: bredde);
}
